#!/usr/bin/env python3
import types
pb=types.ModuleType("pseudobulk_contract")
exec(compile(bytes.fromhex(""),"bundled-pseudobulk-contract","exec"),pb.__dict__)

import os
from pathlib import Path
import sqlite3
import sys

NAMES=['counts.mtx','features.tsv','feature-qc.tsv','columns.tsv','cell-qc.tsv','audit.json']

def run():
    outputs=[Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(6)]
    pb.require([p.name for p in outputs]==NAMES and len({p.parent.absolute() for p in outputs})==1,
               'complete declared output set in one private directory required')
    parent=outputs[0].parent.absolute()
    pb.require(not any(os.path.lexists(p) for p in outputs),'output exists; refusing overwrite')
    pb.require(not any(p.is_symlink() for p in [parent,*parent.parents]),'symlink output ancestor')
    parent.mkdir(parents=True,exist_ok=True)
    bundle=parent/'.pseudobulk-complete'
    pb.require(not os.path.lexists(bundle),'complete bundle already exists')
    result=pb.aggregate(Path(os.environ['AUTONOMICS_INPUT0']),
        {k:Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i,k in enumerate(pb.INPUTS,1)},bundle)
    owned=[]
    try:
        for p in outputs:
            os.link(bundle/p.name,p)
            owned.append((p,p.stat().st_ino))
    except BaseException:
        for p,inode in owned:
            if not p.is_symlink() and p.stat().st_ino==inode:p.unlink()
        raise
    print(__import__('json').dumps({'scope':result['scope'],'scientific_G0_granted':False}))

if __name__=='__main__':
    try:run()
    except (ValueError,OSError,sqlite3.Error,UnicodeError,pb.csv.Error) as e:
        print('BLOCKED: '+str(e),file=sys.stderr);raise SystemExit(2)
